/** Complete Oxywire equipment profiles are distinct from legacy unknown variants. */
export function formatRuneName(id) {
  const raw = String(id || "").replace(/^oxywire:/i, "")
    .replace(/[_-]+/g, " ")
    .replace(/soulreap/gi, "soul reap")
    .replace(/treefeller/gi, "tree feller")
    .replace(/\s+(?:\d+|[ivx]+)$/i, "")
    .trim();
  return raw.replace(/\b\w/g, char => char.toUpperCase());
}

export function romanRuneLevel(level) {
  const number = Number(level);
  return ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][number] || String(level);
}

export function runeTags(variantKey, enchantments) {
  if (!String(variantKey || "").startsWith("oxy2:")) return [];
  return Object.entries(enchantments || {})
    .filter(([id, level]) => /^oxywire:/i.test(id) && Number.isInteger(level) && level > 0)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([id, level]) => {
      return `${formatRuneName(id)} ${romanRuneLevel(level)}`;
    });
}

export function enhancementState(variantKey, enchantments) {
  if (!String(variantKey || "").startsWith("oxy2:")) return "unknown";
  return runeTags(variantKey, enchantments).length ? "runed" : "unruned";
}
